19	}
20	
21	HcclResult InsAlgTemplateRegistry::Register(const std::string& name, const InsAlgTemplateCreator& algTemplateCreator)
22	{
23	    const std::lock_guard<std::mutex> lock(mu_);
24	    if ((tempCreators_.find(name) != tempCreators_.end()) && (tempCreators_[name] != nullptr)) {
25	        HCCL_ERROR("[InsAlgTemplateRegistry]template name[%s] already registered.", name.c_str());
26	        return HcclResult::HCCL_E_INTERNAL;
27	    }
28	    tempCreators_[name] = algTemplateCreator;
29	    return HcclResult::HCCL_SUCCESS;
30	}
31	
32	std::unique_ptr<InsAlgTemplateBase> InsAlgTemplateRegistry::GetAlgTemplate(const std::string& name)
33	{
34	    if (tempCreators_.find(name) == tempCreators_.end()) {
35	        HCCL_ERROR("[InsAlgTemplateRegistry]template name[%s] not found.", name.c_str());
36	        return nullptr;
37	    }
38	
39	    if (tempCreators_[name] == nullptr) {
40	        HCCL_DEBUG("[InsAlgTemplateRegistry]Creator for template name[%s] has not registered.", name.c_str());
