103	HcclResult InsTempAllReduceMesh1DOneShot::RunAllReduce(
104	    const OpParam& param, const std::map<u32, std::vector<ChannelInfo>>& channels,
105	    const std::vector<ThreadHandle>& threads, const TemplateDataParams& tempAlgParams,
106	    const RankSliceInfo& sliceInfoVec)
107	{
108	    HCCL_INFO("[InsTempAllReduceMesh1DOneShot][RunAllReduce] send/recv: rank[%d]", myRank_);
109	
110	    DataSlice usrInSlices
111	        = DataSlice(tempAlgParams.buffInfo.inputPtr, tempAlgParams.buffInfo.inBuffBaseOff, processSize_, count_);
112	    DataSlice usrOutSlices
113	        = DataSlice(tempAlgParams.buffInfo.outputPtr, tempAlgParams.buffInfo.outBuffBaseOff, processSize_, count_);
114	
115	    // 主流 - 本地拷贝
116	    CHK_RET(static_cast<HcclResult>(LocalCopy(threads[0], usrInSlices, usrOutSlices)));
117	
118	    // 特殊场景
119	    if (subCommRanks_[0].size() == 1) {
120	        return HCCL_SUCCESS;
121	    }
122	
123	    // 从流
124	    for (u32 queIdx = 1; queIdx < threadNum_; queIdx++) {
125	        u32 nextRank = (myRank_ + queIdx) % templateRankSize_;
126	        u32 fromRank = subCommRanks_[0][nextRank];
127	        u32 toRank = subCommRanks_[0][nextRank];
128	
129	        const ChannelInfo& linkRecv = channels.at(fromRank)[0]; // linkRecv - 从fromRank接收的链路
130	        const ChannelInfo& linkSend = channels.at(toRank)[0];   // linkSend - 向toRank发送的链路
131	
132	        std::vector<DataSlice> txSrcSlices;
133	        std::vector<DataSlice> txDstSlices;
134	        void* txCclBuffAddr = linkSend.remoteCclMem.addr;
135	        u64 txDstOffset = sliceInfoVec[myRank_][0].offset + tempAlgParams.buffInfo.hcclBuffBaseOff;
136	        u64 txDstSize = sliceInfoVec[myRank_][0].size;
137	        DataSlice txSrcSlice = usrInSlices;
138	        DataSlice txDstSlice = DataSlice(txCclBuffAddr, txDstOffset, txDstSize, count_);
139	        txSrcSlices.push_back(txSrcSlice);
140	        txDstSlices.push_back(txDstSlice);
141	
142	        std::vector<DataSlice> rxSrcSlices;
143	        std::vector<DataSlice> rxDstSlices;
144	        void* rxCclBuffAddr = linkRecv.remoteCclMem.addr;
145	        u64 rxDstOffset = sliceInfoVec[fromRank][0].offset + tempAlgParams.buffInfo.hcclBuffBaseOff;
146	        u64 rxDstSize = sliceInfoVec[fromRank][0].size;
147	        DataSlice rxSrcSlice = usrInSlices;
148	        DataSlice rxDstSlice = DataSlice(rxCclBuffAddr, rxDstOffset, rxDstSize, count_);
149	        rxSrcSlices.push_back(rxSrcSlice);
150	        rxDstSlices.push_back(rxDstSlice);
151	
152	        SendRecvInfo sendRecvInfo{
153	            {linkSend, linkRecv}, {{txSrcSlices, txDstSlices}, {rxSrcSlices, rxDstSlices}}, dataType_};
154	        CHK_PRT_RET(
155	            SendRecvBatchWrite(sendRecvInfo, threads[queIdx]),
156	            HCCL_ERROR("[InsTempAllReduceMesh1DOneShot] RunAllReduce SendRecv failed"), HcclResult::HCCL_E_INTERNAL);
157	    }
158	
159	    return HCCL_SUCCESS;
160	}
