163	    const OpParam& param, const std::vector<ThreadHandle>& threads, const TemplateDataParams& tempAlgParams,
164	    const RankSliceInfo& sliceInfoVec)
165	{
166	    HCCL_INFO("[InsTempAllReduceMesh1DOneShot][RunAllReduce] reduce: rank[%d]", myRank_);
167	    // 增加thread synchronize以支持64类数据类型
168	    if (needAicpuReduce_) {
169	        // 启动任务并等待所有threads任务执行完成
170	        CHK_RET(static_cast<HcclResult>(HcommBatchModeEnd(param.algTag)));
171	        CHK_RET(static_cast<HcclResult>(HcommBatchModeStart(param.algTag)));
172	        for (const auto& thread : threads) {
173	            CHK_RET(static_cast<HcclResult>(HcommThreadJoin(thread, CUSTOM_TIMEOUT)));
174	        }
175	    }
176	
177	    DataSlice usrOutSlices
178	        = DataSlice(tempAlgParams.buffInfo.outputPtr, tempAlgParams.buffInfo.outBuffBaseOff, processSize_, count_);
179	
180	    for (u32 rankIdx = 0; rankIdx < subCommRanks_[0].size(); rankIdx++) {
181	        u32 curRank = rankIdx;
182	        // 遍历除自身外所有rank，计算reduce(scratch, local-usrout)
183	        if (curRank == myRank_) {
184	            continue;
185	        }
186	
