188	        void* RemotePtr = tempAlgParams.buffInfo.hcclBuff.addr;
189	        u64 curSrcOffset = sliceInfoVec[curRank][0].offset + tempAlgParams.buffInfo.hcclBuffBaseOff;
190	        u64 curSrcSize = sliceInfoVec[curRank][0].size;
191	        DataSlice curSrcSlice = DataSlice(RemotePtr, curSrcOffset, curSrcSize, count_);
192	        DataSlice curDstSlice = usrOutSlices;
193	
194	        CHK_RET(static_cast<HcclResult>(LocalReduce(threads[0], curSrcSlice, curDstSlice, dataType_, reduceOp_)));
195	    }
196	    return HCCL_SUCCESS;
197	}
