67	    // maxTmpMemSize_设定为cclIn的大小，op中将申请的HcclBuff全给了cclIn
68	    maxTmpMemSize_ = resCtx.cclMem.size;
69	    // 给channels_和threads_赋值
70	    threads_ = resCtx.threads;
71	    if (param.engine != CommEngine::COMM_ENGINE_AIV && param.engine != CommEngine::COMM_ENGINE_CCU) {
72	        CHK_RET(RestoreChannelMap(resCtx, remoteRankToChannelInfo_));
73	    }
74	    dataCount_ = param.DataDes.count;
75	    dataType_ = param.DataDes.dataType;
76	    dataTypeSize_ = DATATYPE_SIZE_TABLE[param.DataDes.dataType];
77	    if (dataCount_ > UINT64_MAX / dataTypeSize_) {
78	        HCCL_ERROR(
79	            "[InsV2AllReduceSoleExecutor][Orchestrate] dataCount[%llu] * dataTypeSize_[%llu] is greater than "
80	            "UINT64_MAX",
81	            dataCount_, dataTypeSize_);
82	        return HCCL_E_INTERNAL;
83	    }
84	    dataSize_ = dataCount_ * dataTypeSize_;
85	    HcclResult ret = OrchestrateLoop(param, resCtx);
86	    CHK_PRT_RET(
87	        ret != HCCL_SUCCESS,
88	        HCCL_ERROR(
89	            "[InsV2AllReduceSoleExecutor][Orchestrate]errNo[0x%016llx] AllReduce executor kernel run failed",
90	            HCCL_ERROR_CODE(ret)),
91	        ret);
