95	template <typename AlgTopoMatch, typename InsAlgTemplate>
96	HcclResult InsV2AllReduceSoleExecutor<AlgTopoMatch, InsAlgTemplate>::OrchestrateLoop(
97	    const OpParam& param, const AlgResourceCtxSerializable& resCtx)
98	{
99	    HCCL_INFO("[InsV2AllReduceSoleExecutor][OrchestrateLoop] Start");
100	    // 准备资源
101	    TemplateResource templateAlgRes;
102	    if (param.engine == COMM_ENGINE_CCU) {
103	        templateAlgRes.ccuKernels = resCtx.ccuKernels;
104	    }
105	    if (param.engine != CommEngine::COMM_ENGINE_AIV && remoteRankToChannelInfo_.size() > 0) {
106	        templateAlgRes.channels = remoteRankToChannelInfo_[0];
107	    }
108	    templateAlgRes.threads = resCtx.threads;
109	    templateAlgRes.aivCommInfoPtr = resCtx.aivCommInfoPtr;
110	    // 准备数据
111	    TemplateDataParams tempAlgParams;
112	    tempAlgParams.buffInfo.inputPtr = param.inputPtr;
113	    tempAlgParams.buffInfo.outputPtr = param.outputPtr;
114	    tempAlgParams.buffInfo.hcclBuff = resCtx.cclMem;
115	    tempAlgParams.buffInfo.inBuffType = BufferType::INPUT;
116	    tempAlgParams.buffInfo.outBuffType = BufferType::OUTPUT;
117	    tempAlgParams.buffInfo.hcclBuffType = BufferType::HCCL_BUFFER;
118	    tempAlgParams.buffInfo.inputSize = param.inputSize;
119	    tempAlgParams.buffInfo.outputSize = param.outputSize;
120	    tempAlgParams.enableRemoteMemAccess = param.opMode == OpMode::OFFLOAD;
121	    // 不需要重复；repeat用于处理rank存在多块不连续数据块的情况（all-reduce不涉及）
122	    tempAlgParams.repeatNum = 1;
123	    tempAlgParams.inputRepeatStride = 0;
124	    tempAlgParams.outputRepeatStride = 0;
125	
126	    // 构建template
127	    std::shared_ptr<InsAlgTemplate> algTemplate
128	        = std::make_shared<InsAlgTemplate>(param, resCtx.topoInfo.userRank, resCtx.algHierarchyInfo.infos[0]);
129	    if (param.engine == CommEngine::COMM_ENGINE_AICPU_TS
130	        && std::string(param.algName) == "AicpuAllReduceSoleNHRTwoShotMultiLink") {
131	        CHK_RET(algTemplate->SetchannelsPerRank(templateAlgRes.channels));
132	    }
133	    u32 templateScratchMultiplier
134	        = algTemplate->CalcScratchMultiple(tempAlgParams.buffInfo.inBuffType, tempAlgParams.buffInfo.outBuffType);
135	
136	    // 计算最小传输大小
137	    u64 maxDataSizePerLoop = 0;
138	    maxTmpMemSize_ = tempAlgParams.buffInfo.hcclBuff.size;
139	    u64 transportBoundDataSize = (param.engine == CommEngine::COMM_ENGINE_AICPU_TS) ? maxTmpMemSize_ : UB_MAX_DATA_SIZE;
140	    HCCL_INFO("[InsV2AllReduceSoleExecutor]maxTmpMemSize_ [%u]", maxTmpMemSize_);
141	    if (templateScratchMultiplier != 0) {
142	        u64 scratchBoundDataSize
143	            = maxTmpMemSize_ / templateScratchMultiplier / HCCL_MIN_SLICE_ALIGN * HCCL_MIN_SLICE_ALIGN;
144	        maxDataSizePerLoop = std::min(transportBoundDataSize, scratchBoundDataSize);
145	    } else {
146	        maxDataSizePerLoop = transportBoundDataSize;
147	    }
