149	    CHK_PRT_RET(
150	        dataTypeSize_ == 0, HCCL_ERROR("[InsV2AllReduceSoleExecutor][OrchestrateOpbase] dataTypeSize_ is 0"),
151	        HCCL_E_INTERNAL);
152	    u64 maxDataCountPerLoop = maxDataSizePerLoop / dataTypeSize_;
153	    HCCL_INFO(
154	        "[InsV2AllReduceSoleExecutor][OrchestrateOpbase] maxDataCountPerLoop[%llu], maxDataSizePerLoop[%llu], "
155	        "transportBoundDataSize[%llu], templateScratchMultiplier[%llu]",
156	        maxDataCountPerLoop, maxDataSizePerLoop, transportBoundDataSize, templateScratchMultiplier);
157	    CHK_PRT_RET(
158	        maxDataCountPerLoop == 0,
159	        HCCL_ERROR("[InsV2AllReduceSoleExecutor][OrchestrateOpbase] maxDataCountPerLoop is 0"), HCCL_E_INTERNAL);
