    // 计算loopTimes
    u64 loopTimes = dataCount_ / maxDataCountPerLoop
                    + static_cast<u64>(dataCount_ % maxDataCountPerLoop != 0); // 计算迭代轮次（ceil取整）
    // count已经处理的数据
    u64 processedDataCount = 0;
