struct StepSliceInfo {
    BuffInfo buffInfo;
    std::vector<std::vector<u64>> stepCount;     // 每step上所有的rank参与的数据量
    std::vector<std::vector<u64>> stepSliceSize; // 每step上所有的rank参与的数据量
